FROM "Sales Orders"
WHERE date('20' || substr(OrderDate, -2) || '-' || printf('%02d', CAST(substr(OrderDate, 1, instr(OrderDate, '/') - 1) AS INTEGER)) || '-' || printf('%02d', CAST(substr(OrderDate, instr(OrderDate, '/') + 1, instr(substr(OrderDate, instr(OrderDate, '/') + 1), '/') - 1) AS INTEGER))) > date('2018-01-01');

